from timeutil import parse_duration, format_duration

class ParseDurationTest(unittest.TestCase):
    def test_simple_cases(self):
        self.assertEqual(parse_duration("0"), 0)
        self.assertEqual(parse_duration("0s"), 0)
        self.assertEqual(parse_duration("120"), 120)
        self.assertEqual(parse_duration("1h30m"), 5400)
        self.assertEqual(parse_duration("1d1h1m1s"), 86400 + 3600 + 60 + 1)
        self.assertEqual(parse_duration("1h 30m"), 5400)
        self.assertEqual(parse_duration(" 1H30M "), 5400)

    def test_invalid_cases(self):
        invalid_inputs = ["", "-5s", "1.5h", "3w", "h", "30m1h", "1h1h", "1h 30" ]
        for inp in invalid_inputs:
            with self.subTest(inp=inp):
                self.assertRaises(ValueError, parse_duration, inp)

    def test_roundtrip(self):
        for seconds in [0, 1, 59, 60, 61, 3599, 3600, 86400, 90061, 123456]:
            self.assertEqual(parse_duration(format_duration(seconds)), seconds)

if __name__ == "__main__":
    unittest.main()
"}

